<?php
use App\Models\Event; use App\Models\Invitation; use App\Models\QrCode; use Illuminate\Database\Eloquent\Builder; use Livewire\Component;
new class extends Component { public string $eventId=''; public string $invitationId=''; public function with():array{abort_unless(auth()->user()?->can('qr_codes.generate'),403);return ['events'=>$this->accessibleEvents()->orderBy('event_date')->pluck('name','id'),'invitations'=>$this->eventId===''?collect():Invitation::query()->where('event_id',$this->eventId)->with('recipient')->whereDoesntHave('qrCodes')->get()];} public function generate():void{$d=$this->validate(['eventId'=>['required','integer'],'invitationId'=>['required','integer']]);abort_unless($this->accessibleEvents()->whereKey($d['eventId'])->exists(),403);$i=Invitation::query()->where('event_id',$d['eventId'])->findOrFail($d['invitationId']);QrCode::query()->firstOrCreate(['invitation_id'=>$i->id],['token_hash'=>QrCode::generateTokenHash(),'status'=>QrCode::STATUS_ACTIVE,'generated_at'=>now()]);session()->flash('success','QR berhasil dibuat.');$this->redirectRoute('admin.qr-codes');} private function accessibleEvents():Builder{$u=auth()->user();return Event::query()->when(!$u->hasRole('Super Admin'),fn(Builder $q):Builder=>$q->where(fn(Builder $q):Builder=>$q->where('created_by',$u->getKey())->orWhereHas('admins',fn(Builder $q):Builder=>$q->whereKey($u->getKey()))));} };
?>
<div class="mx-auto max-w-3xl space-y-8"><div class="flex flex-wrap items-end justify-between gap-4"><div><h1 class="text-3xl font-semibold text-brand-950">Generate QR</h1></div><a href="{{ route('admin.qr-codes') }}" class="rounded-xl border border-slate-300 px-5 py-3 text-sm font-semibold text-slate-700">Kembali</a></div><form wire:submit="generate" class="space-y-5 rounded-3xl border border-slate-200 bg-white p-6 sm:p-8"><div><label class="text-sm font-semibold text-slate-700">Event</label><select wire:model.live="eventId" class="mt-2 w-full px-4 py-3"><option value="">Pilih event</option>@foreach($events as $id=>$eventName)<option value="{{ $id }}">{{ $eventName }}</option>@endforeach</select></div><div><label class="text-sm font-semibold text-slate-700">Invitation</label><select wire:model="invitationId" class="mt-2 w-full px-4 py-3"><option value="">Pilih invitation</option>@foreach($invitations as $invitation)<option value="{{ $invitation->id }}">{{ $invitation->recipient->name }}</option>@endforeach</select></div><div class="flex justify-end gap-3"><a href="{{ route('admin.qr-codes') }}" class="rounded-xl border border-slate-300 px-5 py-3 font-semibold text-slate-700">Batal</a><button class="rounded-xl bg-brand-950 px-5 py-3 font-semibold text-white">Generate QR</button></div></form></div>